				}
				_, _ = fmt.Fprint(w, catalogBody("second"))
			}))
			defer s.Close()

			names, truncated, err := ListCatalogUnderContext(context.Background(), s.URL, "docker-hosted", "", "", 10, 1000)
			if err != nil {
				t.Fatal(err)
			}
			if got := strings.Join(names, ","); got != "first,second" || truncated {
